import java.util.*;
import java.io.*;

public class Variant2 {
    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String[] parts = br.readLine().split(" ");
        int R = Integer.parseInt(parts[0]);
        int C = Integer.parseInt(parts[1]);
        if (R > C) {
            int temp = R;
            R = C;
            C = temp;
        }
        int[][][] dp = new int[C + 1][1 << R][1 << R];
        for (int i = 0; i <= C; i++) {
            for (int m = 0; m < (1 << R); m++) {
                Arrays.fill(dp[i][m], 69);
            }
        }
        for (int m = 0; m < (1 << R); m++) {
            dp[0][0][m] = 0;
        }
        for (int col = 1; col <= C; col++) {
            for (int prevMask = 0; prevMask < (1 << R); prevMask++) {
                for (int currMask = 0; currMask < (1 << R); currMask++) {
                    for (int nextMask = 0; nextMask < (1 << R); nextMask++) {
                        boolean valid = true;
                        for (int b = 0; b < R; b++) {
                            if ((currMask & (1 << b)) == 0) {
                                boolean neighbor = false;
                                if (b > 0 && (currMask & (1 << (b - 1))) != 0) neighbor = true;
                                if (b + 1 < R && (currMask & (1 << (b + 1))) != 0) neighbor = true;
                                if ((prevMask & (1 << b)) != 0) neighbor = true;
                                if ((nextMask & (1 << b)) != 0) neighbor = true;
                                if (!neighbor) {
                                    valid = false;
                                    break;
                                }
                            }
                        }
                        if (valid) {
                            dp[col][currMask][nextMask] = Math.min(dp[col][currMask][nextMask], dp[col - 1][prevMask][currMask] + Integer.bitCount(prevMask));
                        }
                    }
                }
            }
        }
        int maxUnspiders = 0;
        for (int m = 0; m < (1 << R); m++) {
            maxUnspiders = Math.max(maxUnspiders, R * C - (dp[C][m][0] + Integer.bitCount(m)));
        }
        System.out.println(maxUnspiders);
    }
}
